# typed: strict
# frozen_string_literal: true

# Generated by scripts/release/package_metadata.py. Do not edit.
class Devknx < Formula
  desc "KNX monitor with CLI, TUI, GUI, REST and MCP"
  homepage "https://github.com/metaneutrons/devknx"
  license "GPL-3.0-only"

  on_macos do
    depends_on arch: :arm64
    on_arm do
      url "https://github.com/metaneutrons/devknx/releases/download/v0.5.0/devknx-v0.5.0-aarch64-apple-darwin.tar.gz"
      sha256 "4aef534e328bcd16d327bc77af965c3a838dafd136a2e037e1ee5ed067acdae2"
    end
  end

  on_linux do
    depends_on "libx11"
    depends_on "libxcb"
    depends_on "libxcursor"
    depends_on "libxi"
    depends_on "libxkbcommon"
    depends_on "mesa"
    depends_on "wayland"
    if Hardware::CPU.arm?
      url "https://github.com/metaneutrons/devknx/releases/download/v0.5.0/devknx-v0.5.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "ff042960ce2d1be24953f6c5c35f1e4ec2f0976b71556b24df7a23b1ae8cdff6"
    else
      url "https://github.com/metaneutrons/devknx/releases/download/v0.5.0/devknx-v0.5.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "42cce19d66e1c9d3157fe522eb252f4cdc16a8e8c34dc437f85e3f628378e2c4"
    end
  end

  def install
    root = Dir["devknx", "devknx-v*-*/devknx"].find { |path| File.file?(path) }
    raise "missing devknx executable" unless root

    if OS.linux?
      libexec.install root
      gui_libraries = %w[
        libx11 libxcb libxcursor libxi libxkbcommon mesa wayland
      ].map { |name| formula_opt_lib(name) }
      loader_path = "#{gui_libraries.join(":")}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
      bin.join("devknx").write_env_script libexec/"devknx", LD_LIBRARY_PATH: loader_path
    else
      bin.install root
    end
    source_root = File.dirname(root)
    doc.install File.join(source_root, "THIRD-PARTY-NOTICES.md")
    doc.install File.join(source_root, "licenses")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/devknx --version")
  end
end
